package com.spark.falcon.inventory.entity;
import jakarta.persistence.*;import lombok.*;import java.time.*;
@Entity @Table(name="inventory_audit_events") @Getter @NoArgsConstructor
public class InventoryAuditEvent {@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="business_id",nullable=false)private Long businessId;@Column(name="branch_id",nullable=false)private Long branchId;@Column(name="operation_type",nullable=false,length=30)private String operationType;@Column(name="operation_id",nullable=false)private Long operationId;@Column(nullable=false,length=40)private String action;@Column(name="actor_id",nullable=false)private Long actorId;@Column(length=1000)private String details;@Column(name="occurred_at",nullable=false)private Instant occurredAt;public static InventoryAuditEvent record(Long b,Long branch,String type,Long op,String action,Long actor,String details,Instant now){InventoryAuditEvent e=new InventoryAuditEvent();e.businessId=b;e.branchId=branch;e.operationType=type;e.operationId=op;e.action=action;e.actorId=actor;e.details=details;e.occurredAt=now;return e;}}
